function() {
  var path = {{CG - Ruta de pagina}};
  var base = window.location.protocol + '//' + window.location.host + path;
  var query = new URLSearchParams(window.location.search);
  var clean = new URLSearchParams();
  var utms = ['utm_source','utm_medium','utm_campaign','utm_content','utm_term'];
  var ids = ['gclid','dclid','gbraid','wbraid'];
  if (path === '/404') return base;
  utms.forEach(function(key) {
    var value = query.get(key);
    if (value && value.length <= 100 && /^[a-zA-Z0-9_ -]+$/.test(value) && !/\d{8,}/.test(value)) clean.set(key,value.trim());
  });
  ids.forEach(function(key) {
    var value = query.get(key);
    if (value && /^[a-zA-Z0-9_-]{1,500}$/.test(value)) clean.set(key,value);
  });
  var suffix = clean.toString();
  return base + (suffix ? '?' + suffix : '');
}

function() {
  var stored = {};
  try {
    stored = JSON.parse(window.sessionStorage.getItem('cg_attribution') || '{}');
  } catch (error) {
    stored = {};
  }
  if (!stored || typeof stored !== 'object' || Array.isArray(stored)) {
    stored = {};
  }
  var keys = ['utm_source','utm_medium','utm_campaign','utm_content','utm_term'];
  var query = new URLSearchParams(window.location.search);
  var direct = {};
  var previous = {};
  var allowed = /^[a-zA-Z0-9_ -]+$/;
  var digits = /\d{8,}/;
  var i;
  var key;
  var currentValue;
  var storedValue;
  for (i = 0; i < keys.length; i++) {
    key = keys[i];
    currentValue = query.get(key);
    storedValue = stored[key];
    if (typeof currentValue === 'string' && currentValue.length <= 100 && allowed.test(currentValue) && !digits.test(currentValue)) {
      currentValue = currentValue.replace(/^\s+|\s+$/g, '');
      if (currentValue) direct[key] = currentValue;
    }
    if (typeof storedValue === 'string' && storedValue.length <= 100 && allowed.test(storedValue) && !digits.test(storedValue)) {
      storedValue = storedValue.replace(/^\s+|\s+$/g, '');
      if (storedValue) previous[key] = storedValue;
    }
  }
  if (direct.utm_source || direct.utm_medium || direct.utm_campaign) {
    return direct;
  }
  return previous;
}

function() {
  var raw = {{CG - DL - page_referrer}};
  if (typeof raw !== 'string') raw = document.referrer || '';
  if (!raw) return '';
  try {
    var url = new URL(raw);
    if (!/^https?:$/.test(url.protocol)) return '';
    var origin = window.location.protocol + '//' + window.location.host;
    if (url.origin !== origin) return url.origin;
    var path = url.pathname.replace(/\/+$/, '') || '/';
    var paths = ["/", "/especializacion", "/programas/gastronomia", "/programas/pasteleria", "/programas/bar-profesional", "/programas/barismo", "/programas/sommelier", "/programas/cocina-acelerada", "/talleres/fast-food", "/talleres/limonadas-y-triples", "/talleres/pasteleria-boutique"];
    return url.origin + (paths.indexOf(path) >= 0 ? path : '/404');
  } catch (error) { return ''; }
}

